#!/usr/bin/env python3
"""Board audit m17884 — independent re-derivation for m17839 (TensorLBM).

Anchor: XVAL-LBM-FUSED-PUSH-PULL-AA-PATTERN
Target mission: 17839 (worktree /root/tp-agent/work/m17839, commit eee0988a)

Reads, without trusting the deliverable's prose:
  * committed run artifact  xval/fused_push_pull_aa_pattern/result.json
  * auditor fresh re-run    (generated by run.py --out /tmp/audit_m17839_result.json)
  * tensor_benchmark_cases  (psql, anchor_slug lookup)
and re-derives every graded number.  Writes audit_numbers.json + 3 figures.
"""
from __future__ import annotations

import json
import math
import subprocess
import sys
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
WORK = Path("/root/tp-agent/work/m17839")
XV = WORK / "xval" / "fused_push_pull_aa_pattern"
COMMITTED = XV / "result.json"
FRESH = Path("/tmp/audit_m17839_result.json")
GATE, TARGET = 0.15, 0.03

committed = json.loads(COMMITTED.read_text())
fresh = json.loads(FRESH.read_text()) if FRESH.exists() else None


def walk_diff(a, b, path=""):
    """Structural numeric diff; returns list of (path, kind, old, new)."""
    out = []
    if isinstance(a, dict):
        if not isinstance(b, dict):
            return [(path, "type", type(a).__name__, type(b).__name__)]
        for k in a:
            if k not in b:
                out.append((path + "/" + k, "missing_in_fresh", a[k], None))
            else:
                out += walk_diff(a[k], b[k], path + "/" + k)
        for k in b:
            if k not in a:
                out.append((path + "/" + k, "extra_in_fresh", None, b[k]))
    elif isinstance(a, list):
        if not isinstance(b, list) or len(a) != len(b):
            return [(path, "len", len(a), None if not isinstance(b, list) else len(b))]
        for i, (x, y) in enumerate(zip(a, b)):
            out += walk_diff(x, y, f"{path}[{i}]")
    elif isinstance(a, bool) or isinstance(b, bool):
        if a != b:
            out.append((path, "val", a, b))
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
        both_nan = isinstance(a, float) and isinstance(b, float) and math.isnan(a) and math.isnan(b)
        if a != b and not both_nan:
            out.append((path, "num", a, b))
    else:
        if a != b:
            out.append((path, "val", a, b))
    return out


diff = walk_diff(committed, fresh) if fresh else []
numeric_diffs = {d[0]: {"committed": d[2], "fresh": d[3]} for d in diff}

# ---- re-derive graded numbers straight from the artifact -------------------
base = committed["base"]
grade = {
    "ux_rel_l2_oss": committed["verdict"]["ux_err_oss"],
    "uy_rel_l2_oss": committed["verdict"]["uy_err_oss"],
    "rho_rel_l2_oss": committed["verdict"]["rho_err_oss"],
    "ux_rel_l2_torch_fused": committed["verdict"]["ux_err_torch_fused"],
    "ux_rel_l2_torch_ab": committed["verdict"]["ux_err_torch_ab"],
    "nu_fit_oss": base["oss_numpy"]["nu_inversion"]["nu_fit"],
    "nu_ref": committed["base_cfg"]["nu"],
    "nu_rel_err": abs(base["oss_numpy"]["nu_inversion"]["nu_fit"] - committed["base_cfg"]["nu"])
    / committed["base_cfg"]["nu"],
    "mass_final_oss": base["oss_numpy"]["mass_final"],
    "mass_expected": committed["base_cfg"]["rho0"] * committed["base_cfg"]["nx"] * committed["base_cfg"]["ny"],
    "cross_arm_oss_vs_torch_fused_rel_l2": committed["verdict"]["cross_arm_rel_l2"],
    "cross_arm_ux_rel_l2_oss_vs_torch_fused": committed["verdict"]["oss_vs_fused_ux_rel_l2"],
    "ab_vs_fused_ux_rel_l2": committed["verdict"]["ab_vs_fused_ux_rel_l2"],
}
grade["mass_rel_err_oss"] = abs(grade["mass_final_oss"] - grade["mass_expected"]) / grade["mass_expected"]
grade["ux_gate_pass"] = grade["ux_rel_l2_oss"] < GATE
grade["ux_target_3pct_pass"] = grade["ux_rel_l2_oss"] < TARGET
grade["rho_gate_pass"] = grade["rho_rel_l2_oss"] < GATE
grade["rho_target_3pct_pass"] = grade["rho_rel_l2_oss"] < TARGET
grade["nu_gate_pass"] = grade["nu_rel_err"] < GATE

# resolution ladder re-derived (not copied from verdict block)
res = committed["resolution"]
ladder = [
    {"nx": r["cfg"]["nx"], "steps": r["cfg"]["nsteps"], "k": r["nondim"]["k_lu"],
     "ux_rel_l2": r["oss_final"]["ux_lu2"], "rho_rel_l2": r["oss_final"]["rho_lu2"],
     "nu_rel_err": r["nu_inversion"]["rel_err"]}
    for r in res
]
orders = [math.log(ladder[i]["ux_rel_l2"] / ladder[i + 1]["ux_rel_l2"]) / math.log(2.0)
          for i in range(len(ladder) - 1)]
grade["resolution_order_rederived"] = orders
grade["resolution_order_recorded"] = committed["verdict"]["resolution_order"]
grade["order_match"] = bool(np.allclose(orders, committed["verdict"]["resolution_order"], rtol=1e-9))

# acoustic-period prediction used to explain the density residual
nondim = committed["nondim"]
cs = nondim["c_s_lu"]
k2 = 2.0 * nondim["k_lu"]
t_half_pred = math.pi / (cs * k2)
grade["rho_envelope_period_predicted"] = t_half_pred
grade["rho_envelope_period_measured"] = committed["verdict"]["rho_envelope_period"]
grade["rho_envelope_period_rel_err"] = abs(t_half_pred - committed["verdict"]["rho_envelope_period"]) / t_half_pred

# ---- independent magnitude check of the rho diagnostic (A4) ----------------
sys.path.insert(0, str(XV))
import oss_port  # noqa: E402

st = oss_port.OSSFusedStepper(64, 64, 1 / 6.0, 0.02, 1.0)
for _ in range(800):
    st.step(save=False)
st.step(save=True)  # moment buffers only hold the current state when save=True
ra, uxa, uya = oss_port.taylor_green_eval(801, 64, 64, 1 / 6.0, 0.02, 1.0)
er = st.rho - ra
abs_check = {
    "t_eval": 801,
    "abs_rho_err_max": float(abs(er).max()),
    "abs_rho_err_rms": float(np.sqrt((er ** 2).mean())),
    "analytic_rho_fluct_rms": float(np.sqrt(((ra - 1.0) ** 2).mean())),
    "rel_l2_rho_t801": float(np.linalg.norm(er) / np.linalg.norm(ra - 1.0)),
    "abs_ux_err_max": float(abs(st.ux - uxa).max()),
    "rel_l2_ux_t801": float(np.linalg.norm(st.ux - uxa) / np.linalg.norm(uxa)),
}
grade["rho_magnitude_check"] = abs_check

controls = {name: {
    "analytic_ux_or_uy_err": c.get("final", {}).get("ux_lu2") if c.get("final") else None,
    "gate": c.get("gate") or c.get("gate_analytic_ux") or c.get("gate_analytic_uy"),
    "cross_arm_ux_rel_l2": c.get("cross_arm_mac_vs_oss", {}).get("ux_rel_l2"),
} for name, c in committed["controls"].items()}
for name, c in committed["controls"].items():
    if c.get("final"):
        controls[name]["analytic_ux_or_uy_err"] = max(c["final"]["ux_lu2"], c["final"]["uy_lu2"])

# ---- machine judge: registered benchmark cases for this anchor ------------
try:
    out = subprocess.run(
        ["psql", "-U", "foundation", "-d", "tensorplatform", "-At", "-F", "|", "-c",
         "SELECT case_name,metric,tolerance FROM tensor_benchmark_cases "
         "WHERE anchor_slug='XVAL-LBM-FUSED-PUSH-PULL-AA-PATTERN'"],
        capture_output=True, text=True, timeout=60, check=False)
    judge_rows = [r for r in out.stdout.strip().splitlines() if r]
    judge_err = out.stderr.strip()[-300:] if out.returncode else ""
except Exception as exc:  # pragma: no cover
    judge_rows, judge_err = [], repr(exc)

total_cases = subprocess.run(
    ["psql", "-U", "foundation", "-d", "tensorplatform", "-At", "-c",
     "SELECT count(*) FROM tensor_benchmark_cases"], capture_output=True, text=True).stdout.strip()

# ---- integration: is the new module reachable from library code? ----------
grep = subprocess.run(["grep", "-rn", "fused_push_pull", "--include=*.py", str(WORK / "src"),
                       str(WORK / "benchmarks"), str(WORK / "examples")],
                      capture_output=True, text=True).stdout.strip()
export = subprocess.run(["grep", "-c", "fused_push_pull", str(WORK / "src" / "tensorlbm" / "__init__.py")],
                        capture_output=True, text=True).stdout.strip()

numbers = {
    "anchor": committed["anchor"],
    "target_mission": 17839,
    "target_commit": subprocess.run(["git", "-C", str(WORK), "rev-parse", "HEAD"],
                                    capture_output=True, text=True).stdout.strip(),
    "gate": GATE, "target": TARGET,
    "auditor_fresh_run": "python xval/fused_push_pull_aa_pattern/run.py --out /tmp/audit_m17839_result.json "
                         "(2026-11-13, same worktree/commit; completed in <2 min)",
    "repro_numeric_diffs": numeric_diffs,
    "repro_diff_count": len(diff),
    "repro_non_timing_diff_count": len([d for d in diff if not d[0].endswith("wall_s")]),
    "grade": grade,
    "resolution_ladder": ladder,
    "controls": controls,
    "storage": committed["storage"],
    "benchmark_judge": {
        "table": "tensor_benchmark_cases",
        "rows_for_anchor": len(judge_rows),
        "rows": judge_rows,
        "total_registered_cases": total_cases,
        "query_error": judge_err,
        "note": "board rule: the registered case row is the sole judge; 0 rows -> L4 not confirmable",
    },
    "integration": {
        "grep_src_benchmarks_examples": grep or "(no hits outside the module itself)",
        "init_export_hits": export,
        "callers_outside_xval_and_tests": 0 if not grep.replace(
            "src/tensorlbm/fused_push_pull.py", "").strip() else None,
    },
    "external_anchor": {
        "upstream_repo": "lbm-principles-practice/code (MIT, Krugers et al. 2016)",
        "snapshot_files": committed["oss_ref"],
        "snapshot_sha256_reverified": True,
        "upstream_binary_executed": False,
        "note": "the 'OSS' arm is a NumPy transliteration by the same author; the CUDA source was "
                "snapshotted and read, never compiled/executed (no GPU). Analytic TG is exact.",
    },
    "tests": {"file": "tests/test_fused_push_pull_xval.py", "auditor_run": "12 passed in 6.21s"},
}
(HERE / "audit_numbers.json").write_text(json.dumps(numbers, indent=1, default=float))
print(json.dumps({k: numbers[k] for k in
                  ["repro_diff_count", "repro_non_timing_diff_count", "grade", "controls"]},
                 indent=1, default=float)[:2000])

# ---------------------------- figures -------------------------------------
import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

FIG = HERE / "figures"
FIG.mkdir(parents=True, exist_ok=True)

# fig1: analytic gate / target status per graded quantity
fig, ax = plt.subplots(figsize=(7.0, 3.6), dpi=150)
labels = ["u_x rel.L2", "u_y rel.L2", "rho rel.L2", "nu inv. rel.err"]
vals = [grade["ux_rel_l2_oss"], grade["uy_rel_l2_oss"], grade["rho_rel_l2_oss"], grade["nu_rel_err"]]
colors = ["#2e7d32" if v < TARGET else ("#f9a825" if v < GATE else "#c62828") for v in vals]
bars = ax.bar(labels, vals, color=colors)
ax.set_yscale("log")
ax.axhline(GATE, color="#c62828", ls="--", lw=1.2, label="owner gate 15%")
ax.axhline(TARGET, color="#2e7d32", ls=":", lw=1.2, label="target 3%")
for b, v in zip(bars, vals):
    ax.text(b.get_x() + b.get_width() / 2, v * 1.15, f"{v:.4g}", ha="center", fontsize=8)
ax.set_ylabel("relative error (log)")
ax.set_title("m17839 re-derived grades vs analytic Taylor-Green (NX=64, tau=1, T=800)")
ax.legend(fontsize=8, loc="lower right")
fig.tight_layout()
fig.savefig(FIG / "fig1_grades_vs_analytic.png")
plt.close(fig)

# fig2: resolution ladder, re-derived orders
fig, ax = plt.subplots(figsize=(6.2, 4.0), dpi=150)
nx = [p["nx"] for p in ladder]
h = [1.0 / n for n in nx]
ax.loglog(h, [p["ux_rel_l2"] for p in ladder], "o-", label="u_x rel.L2 (got)")
ax.loglog(h, [p["rho_rel_l2"] for p in ladder], "s-", label="rho rel.L2 (got)")
ax.loglog(h, [h[1] ** 2 / h[1] ** 2 * ladder[1]["ux_rel_l2"] * (hi / h[1]) ** 2 for hi in h],
          "k--", lw=1.0, label="slope 2 reference")
ax.axhline(GATE, color="#c62828", ls="--", lw=1.0, label="gate 15%")
ax.axhline(TARGET, color="#2e7d32", ls=":", lw=1.0, label="target 3%")
for p, hi in zip(ladder, h):
    ax.annotate(f"NX={p['nx']}", (hi, p["ux_rel_l2"]), textcoords="offset points", xytext=(4, -12), fontsize=7)
ax.set_xlabel("h = 1/NX"); ax.set_ylabel("relative L2 error")
ax.set_title(f"resolution ladder, observed orders = {orders[0]:.2f}, {orders[1]:.2f}")
ax.legend(fontsize=7)
fig.tight_layout()
fig.savefig(FIG / "fig2_resolution_ladder.png")
plt.close(fig)

# fig3: controls (can the gate fail?) + reproduction diff scope
fig, (a1, a2) = plt.subplots(1, 2, figsize=(9.0, 3.6), dpi=150)
names = list(controls)
cvals = [controls[n]["analytic_ux_or_uy_err"] or 0.0 for n in names]
a1.bar(names, cvals, color=["#c62828" if v >= GATE else "#9e9e9e" for v in cvals])
a1.axhline(GATE, color="#c62828", ls="--", lw=1.1)
a1.set_yscale("log"); a1.set_ylabel("analytic rel.L2 error")
a1.set_title("negative controls (gate must fail)")
for i, v in enumerate(cvals):
    a1.text(i, v * 1.15, f"{v:.3f}", ha="center", fontsize=8)
kinds = ["total numeric diffs (fresh re-run vs committed result.json)",
         "of which non-timing"]
a2.bar(["diff entries", "wall_s only"], [numbers["repro_diff_count"], numbers["repro_non_timing_diff_count"]],
       color=["#1565c0", "#2e7d32"])
for i, v in enumerate([numbers["repro_diff_count"], numbers["repro_non_timing_diff_count"]]):
    a2.text(i, v + 0.05, str(v), ha="center", fontsize=9)
a2.set_title("reproducibility: fresh re-run vs shipped artifact")
fig.tight_layout()
fig.savefig(FIG / "fig3_controls_and_repro.png")
plt.close(fig)
print("figures ->", sorted(p.name for p in FIG.glob("*.png")))